#include <stdio.h>

static int soma_digitos(int x) {
    int s = 0;
    while (x > 0) {
        s += x % 10;
        x /= 10;
    }
    return s;
}

int main(void) {
    int n, m, s;
    if (scanf("%d %d %d", &n, &m, &s) != 3) {
        return 0;
    }

    int ans = -1;
    for (int i = m; i >= n; i--) {
        if (soma_digitos(i) == s) {
            ans = i;
            break;
        }
    }

    printf("%d\n", ans);
    return 0;
}
